"""
board=[
["X","O","X","X"],
["O","X","O","X"],
["X","O","X","O"],
["O","X","O","X"]]
"""

class Solution:
    def solve(self, board: List[List[str]]) -> None:
        m, n = len(board), len(board[0])
        DIR = [0,1,0,-1,0]
        not_valid = set()

        def dfs(r: int, c: int, mark: bool) -> None:
            if not (0 <= r < m and 0 <= c < n and board[r][c] == "O"):
                return

            if mark:
                board[r][c] = "X"
            else:
                not_valid.add((r, c))

            for i in range(4):
                nr, nc = r + DIR[i], c + DIR[i + 1]
                if 0 <= nr < m and 0 <= nc < n and board[nr][nc] == "O" and (nr, nc) not in not_valid:
                    dfs(nr, nc, mark)

        for i in [0, m - 1]:
            for j in range(n):
                if board[i][j] == "O":
                    dfs(i, j, False)

        for j in [0, n - 1]:
            for i in range(m):
                if board[i][j] == "O":
                    dfs(i, j, False)

        for i in range(m):
            for j in range(n):
                if board[i][j] == "O" and (i, j) not in not_valid:
                    dfs(i, j, True)
